const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<img src="assets/icon-${n}.svg" width="24" height="24" alt="">`, mark=`<img class="mark" src="assets/nasaq-mark.svg" alt="رمز نسق">`;
const groups=[['ابدأ هنا · START',['overview','نظرة عامة','Overview'],['start','الاستخدام','Get started']],['الأسس · FOUNDATIONS',['colors','الألوان','Colors'],['typography','الخطوط','Typography'],['logos','الشعار','Logos'],['icons','الأيقونات','Icons'],['misc','الرموز التعبيرية','Misc icons'],['effects','التأثيرات','Effects'],['spacing','المسافات والشبكات','Spacing & grids']],['المكونات · COMPONENTS',['buttons','الأزرار','Buttons'],['inputs','حقول الإدخال','Inputs'],['select','القوائم المنسدلة','Select'],['checkbox','مربعات الاختيار','Checkbox'],['switch','مفاتيح التبديل','Switch'],['tabs','التبويبات','Tabs'],['badge','الشارات','Badge'],['avatar','الصور الرمزية','Avatar'],['dialog','النوافذ الحوارية','Dialog'],['tooltip','التلميحات','Tooltip']],['تركيبات · PATTERNS',['marketing','مكونات التسويق','Marketing'],['patterns','واجهات الذكاء الاصطناعي','AI patterns']],['للمصممين والمطورين',['tokens','المتغيرات','Tokens'],['skill','مهارة نسق','AI skill'],['downloads','التحميلات','Downloads']]];
groups[2].push(...[["radio", "الاختيار الواحد", "Radio"], ["textarea", "النص الطويل", "Textarea"], ["alert", "رسائل التنبيه", "Alert"], ["progress", "التقدم", "Progress"], ["skeleton", "التحميل الهيكلي", "Skeleton"], ["accordion", "المحتوى المطوي", "Accordion"], ["cards", "البطاقات", "Cards"], ["breadcrumb", "مسار التنقل", "Breadcrumb"]]);
groups[4].splice(1,0,['brand','حزمة الهوية','Brand kit'],['ai-guide','AI في مشروعك','AI integration'],['mcp','واجهة MCP','MCP server']);
groups[4].splice(1,0,['npm','حزمة npm','npm package']);
