const pages=groups.flatMap(g=>g.slice(1));
$('#side-nav').innerHTML=groups.map(g=>`<div class="nav-group"><h2>${g[0]}</h2>${g.slice(1).map(p=>`<a href="#${p[0]}" data-page="${p[0]}"><span>${p[1]}</span><small>${p[2]}</small></a>`).join('')}</div>`).join('');
const code=s=>`<div class="code-block"><button data-copy="${esc(s)}" aria-label="نسخ المثال">Copy</button><pre><code>${esc(s)}</code></pre></div>`;
const section=(id,title,html)=>`<section class="section" id="${id}"><h2>${title}</h2>${html}</section>`;
const head=(id,desc)=>{let p=pages.find(p=>p[0]===id);return `<div class="breadcrumb">نسق / ${p[2]}</div><header class="page-head"><div class="eyebrow">${p[2]} · NASAQ 1.3</div><h1>${p[1]}</h1><p>${desc}</p></header>`};
const preview=(html,label='LIVE PREVIEW')=>`<div class="preview"><div class="demo-label">${label}</div>${html}</div>`;
const table=(headers,rows)=>`<table class="spec-table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const footer=()=>`<footer class="footer-note"><span>نسق — نظام تصميم عربي لمنتجات الذكاء الاصطناعي.</span><span>مستوحى بصريًا من <a href="https://thmanyah.com/" target="_blank" rel="noopener">ثمانية</a> · <a href="case-study.html">دراسة المشروع ↗</a></span></footer>`;
const tile=(id,art,bg='')=>{let p=pages.find(p=>p[0]===id);return `<a href="#${id}" class="tile"><div class="tile-art" ${bg?`style="background:${bg}"`:''}>${art}</div><div class="tile-text"><h3>${p[1]} ↖</h3><small>${p[2]}</small></div></a>`};
const palette=[['paper','#F5F2ED','ورق / الخلفية'],['white','#FFFFFF','الأسطح'],['ink','#171717','الحبر / النص'],['red','#FF3B25','الهوية'],['red-strong','#B82413','روابط وأخطاء'],['pink','#F6B8D0','أفكار'],['lavender','#CEC5E5','مساعدون'],['mint','#CDE7D8','نجاح'],['yellow','#FFD45C','تنبيه'],['muted','#68635F','نص ثانوي'],['line','#DCD6CE','حدود'],['success','#256445','نص النجاح']];
function overview(){return `<div class="breadcrumb">التوثيق / مرحبًا بك في نسق</div><header class="page-head overview-intro"><div class="eyebrow">NASAQ · ARABIC AI DESIGN SYSTEM</div><h1>نظام نسق للتصميم</h1><p>أسس ومكونات وأنماط لمنتجات عربية واضحة. استكشف المكتبة، أو ابدأ من ملفات النظام.</p><div class="row"><a class="nq-button secondary" href="#start">دليل البدء ←</a><a class="tag-link" href="#downloads">ملفات النظام ↓</a></div></header><div class="overview-meta"><span>٨ مجموعات أسس</span><span>١٨ مكونًا</span><span>٦ مكونات تسويقية</span><span>RTL FIRST / LIGHT + DARK</span></div><section class="section" id="foundations"><div class="section-head"><div><h2>من الأساس، إلى كل تفصيل.</h2><p>لغة بصرية واحدة. مساحة لا نهائية للتعبير.</p></div><a href="#tokens">استكشف المتغيرات ↖</a></div><div class="tiles">${tile('colors',`<div class="color-dots">${palette.slice(0,8).map(p=>`<i style="background:${p[1]};border:1px solid #17171710"></i>`).join('')}</div>`)}${tile('typography','<span class="type-sample">أبجد Aa</span>','#CEC5E5')}${tile('logos',mark,'#F6B8D0')}${tile('icons',`<div class="row">${['search','chat','spark','mic'].map(icon).join('')}</div>`)}${tile('spacing',`<div class="mini-grid">${'<i></i>'.repeat(12)}</div>`,'#CDE7D8')}${tile('effects','<div style="width:100px;height:64px;background:white;border-radius:12px;box-shadow:0 8px 24px #17171720"></div>')}</div></section><section class="section" id="building"><div class="section-head"><div><h2>مكونات، تعمل معًا.</h2><p>حالات واضحة. تفاعل مألوف. تفاصيل عربية.</p></div><a href="#buttons">تصفّح المكونات ↖</a></div><div class="tiles">${tile('buttons','<span class="nq-button">ابدأ محادثة ←</span>')}${tile('inputs','<div style="width:80%" class="nq-input">بماذا تفكّر اليوم؟</div>')}${tile('badge','<span class="nq-badge">✦ مساعد الكتابة</span><span class="nq-badge success">متاح</span>')}</div></section><section class="section" id="ai"><div class="skill-banner"><div><span class="eyebrow">DESIGNED FOR PEOPLE. READY FOR AI.</span><h2>أرفق المهارة. ودع نسق يتولّى الشكل.</h2><p>قواعد جاهزة لمساعدك: الألوان، الخطوط، المكونات، والمنطق العربي.</p></div><a class="nq-button" href="#skill">اكتشف مهارة نسق ↖</a></div></section>`}
function colors(){return head('colors','الحبر والورق هما القاعدة. الأحمر للحضور. والألوان الهادئة تمنح المحتوى مساحة للتعبير.')+section('palette','اللوحة الأساسية',`<div class="swatches">${palette.map(p=>`<div class="swatch"><div class="swatch-color" style="background:${p[1]};color:#171717">${p[0]==='red'?'✳':''}</div><div class="swatch-body"><b>${p[0]}</b><span style="font-size:12px">${p[2]}</span><br><button data-copy="${p[1]}" aria-label="نسخ اللون ${p[0]}">${p[1]} ⧉</button></div></div>`).join('')}</div>`)+section('contrast','ألوان مقروءة',table(['الاستخدام','النص','الخلفية','القاعدة'],[['النص الأساسي','#171717','#F5F2ED','محتوى وأزرار'],['نص ثانوي','#68635F','#F5F2ED','تسميات ووصف'],['رابط أو خطأ','#B82413','#FFFFFF','تمييز + وصف مكتوب'],['زر الهوية','#171717','#CDE7D8','سطح نعناعي مع نص حبر']])+`<p class="note">الألوان الفاتحة للخلفيات، مع نص داكن. لا تعتمد على اللون وحده لشرح النجاح أو الخطأ.</p>`)+section('theme','Light / Dark',preview('<div class="row"><div class="nq-card" style="background:#F5F2ED;color:#171717;flex:1"><b>نهار هادئ.</b><p style="color:#68635F">حبر على ورق.</p></div><div class="nq-card" style="background:#171717;color:#F5F2ED;flex:1"><b>ليل واضح.</b><p style="color:#CEC5E5">ورق على حبر.</p></div></div>')+code('<html lang="ar" dir="rtl" data-theme="dark">\n  <body class="nq">…</body>\n</html>'))}
function logos(){return head('logos','نسق يعني ترتيبًا يصنع المعنى. خمس وحدات مربّعة تلتقي: أفكار مختلفة، في نظام واحد.')+section('identity','الهوية',preview(`<div class="row" style="justify-content:space-around;min-height:150px">${mark}<span style="font:700 80px var(--nq-font-display)">نسق</span><span style="font:32px Arial">Nasaq</span></div>`)+`<p>الاسم العربي مكتوب بـ Almarai. الرمز SVG مستقل وقابل للتلوين. هذا تركيب طباعي، وليس خطًا حصريًا.</p><a class="nq-button secondary" href="assets/nasaq-mark.svg" download>تحميل الرمز SVG ↓</a> <a class="nq-button secondary" href="assets/nasaq-lockup.svg" download>تحميل التركيب SVG ↓</a>`)+section('clearspace','المساحة والحجم',table(['القاعدة','القيمة'],[['مساحة خالية','وحدة واحدة = ¼ عرض الرمز من كل جهة'],['الحد الأدنى الرقمي','24px للرمز، 100px للتركيب'],['ألوان مقبولة','الحبر، الورق، لون أحادي متباين'],['تجنّب','التمدد، الميل، الظلال، تغيير ترتيب الوحدات']])+code('<img src="assets/nasaq-mark.svg" width="32" height="32" alt="نسق">'))}
const iconNames=["settings", "link", "stop", "refresh", "lock", "user", "folder", "trash", "info", "chevron", "upload", "moon"].concat(['search','arrow','plus','close','copy','download','chat','spark','check','menu','sun','file','mic','grid']);
function spacing(){return head('spacing','إيقاع مبني على 4px. شبكات متجاوبة، حواف هادئة، ومساحات تعطي العربية حقّها.')+section('space','المسافات',preview([4,8,12,16,24,32,48,64,96].map(n=>`<div class="spacing-row"><code>${n}px</code><i style="width:${n*2}px"></i><span class="token-name">--nq-space-${n}</span></div>`).join('')))+section('radius','الحواف',preview('<div class="row">'+[['none',0],['sm',4],['md',12],['lg',20],['pill',999]].map(x=>`<div style="text-align:center"><div class="radius-demo" style="border-radius:${x[1]}px">${x[1]}</div><small>${x[0]}</small></div>`).join('')+'</div>'))+section('grid','الشبكات المتجاوبة',preview(`<div class="grid-demo">${'<i></i>'.repeat(12)}</div>`)+table(['الجهاز','الأعمدة','الفجوة','الهامش'],[['Desktop ≥ 1024px','12','24px','48–64px'],['Tablet 641–1023px','8','24px','24–32px'],['Mobile ≤ 640px','4','16px','20–24px']])+code('.layout { display:grid; grid-template-columns:repeat(12,minmax(0,1fr)); gap:24px; }\n@media (max-width:1023px) { .layout { grid-template-columns:repeat(8,minmax(0,1fr)); } }\n@media (max-width:640px) { .layout { grid-template-columns:repeat(4,minmax(0,1fr)); gap:16px; } }')+`<p class="note">عرض المحتوى الأقصى 1200px، النص الطويل 65 حرفًا تقريبًا. استخدم margin-inline وpadding-inline بدل left/right لتدعم RTL.</p>`)}
