function component(id){let e=examples[id];return head(id,e.desc)+section('preview','جرّب المكوّن',preview(e.html))+section('states','الحالات المرئية',stateGallery(id))+section('anatomy','التكوين والحالات',table(['الخاصية','القيم','ملاحظة'],e.props))+section('implementation','الاستخدام في الكود',code(e.snippet)+`<p class="note">${e.rule}</p>`)+section('accessibility','إمكانية الوصول',`<p>تحقق من التركيز المرئي، لوحة المفاتيح، التسمية، واتجاه RTL. أمثلة نسق تستخدم عناصر HTML الأصلية كلما أمكن. أضف منطق المنتج الفعلي في تطبيقك.</p>`)}
function marketing(){return head('marketing','من ثمانية نستعير إيقاع المحتوى: عناوين كبيرة، تقسيمات واضحة، ومجموعات لونية لها شخصية. هنا نطبقه على منتج AI.')+section('hero','01 / Hero',preview('<div class="nq-hero"><span class="eyebrow" style="color:#171717">NASAQ</span><h2>أفكارك،<br>بصوتك أنت.</h2><p>مساعد عربي للكتابة والبحث. يمنحك مساحة للفكرة، ويحافظ على أسلوبك.</p><a class="nq-button" href="#patterns">جرّب المثال ←</a></div>')+code('<section class="nq-hero">\n <h2>أفكارك، بصوتك أنت.</h2>\n <p>مساعد عربي للكتابة والبحث.</p>\n <a class="nq-button" href="/start">ابدأ الآن</a>\n</section>'))+section('editorial','02 / Editorial cards',preview('<div class="tiles">'+[['#CEC5E5','✦','من الفكرة إلى مسودة.','دليل الكتابة'],['#F6B8D0','✳','أسئلة أفضل، أجوبة أوضح.','دليل البحث'],['#CDE7D8','↖','رتّب معرفتك.','دليل المشاريع']].map(x=>`<article class="tile"><div class="tile-art" style="background:${x[0]};font-size:70px">${x[1]}</div><div style="padding:20px"><small>${x[3]}</small><h3 style="font:700 25px var(--nq-font-display)">${x[2]}</h3><a class="tag-link" href="#patterns">استكشف المثال ↖</a></div></article>`).join('')+'</div>'))+section('newsletter','03 / Newsletter',preview('<div class="nq-newsletter"><h3>شيء يستحق بريدك.</h3><p>مثال واجهة فقط. لا يجمع عناوين ولا يرسل رسائل.</p><form id="newsletter-demo"><label for="newsletter-email" class="sr-only">البريد الإلكتروني</label><input id="newsletter-email" class="nq-input" type="email" dir="ltr" placeholder="you@example.com" required><button class="nq-button" type="submit">جرّب الاشتراك</button></form><p id="newsletter-status" role="status"></p></div>'))+section('pricing','04 / Pricing',preview('<div class="tiles">'+[['شخصي','مجاني','للاستكشاف والتجربة.'],['محترف','٤٩ ر.س','سعر توضيحي / شهري'],['فريق','تواصل معنا','لعمل مشترك، بنسق واحد.']].map((x,i)=>`<article class="nq-card" ${i===1?'style="border:2px solid var(--nq-text)"':''}><span class="nq-badge">${i===1?'الأكثر شمولًا':'خطة توضيحية'}</span><h3>${x[0]}</h3><b style="font-size:28px">${x[1]}</b><p>${x[2]}</p><button class="nq-button ${i===1?'':'secondary'}" data-toast="هذه خطة توضيحية؛ لا يتم شراء اشتراك.">استكشف الخطة</button></article>`).join('')+'</div>'))+section('faq','05 / FAQ',preview('<div class="nq-faq"><details open><summary>هل نسق نظام عربي من البداية؟</summary><p>نعم. الاتجاه، الخطوط، النصوص، والمسافات صُممت للعربية أولًا.</p></details><details><summary>هل يمكن استخدامه في مشروع إنجليزي؟</summary><p>نعم. استخدم dir=ltr واحتفظ بالخصائص المنطقية. تحتاج إلى مراجعة الخط الإنجليزي ومحتوى الواجهة.</p></details><details><summary>هل أمثلة AI متصلة بنموذج؟</summary><p>لا. هي أمثلة تفاعلية محلية لشرح أنماط الواجهة.</p></details></div>'))+section('footer','06 / Footer',preview('<footer class="nq-footer"><div><strong style="font:700 32px var(--nq-font-display)">نسق</strong><p>لغة تصميم، أقرب إلى الناس.</p></div><div class="row"><a href="#start">ابدأ</a><a href="#tokens">المتغيرات</a><a href="#skill">مهارة AI</a></div></footer>'))+section('source','ملفات المكونات التسويقية',`<p>تحميل ملف أمثلة مستقل يحتوي على المكونات الستة مع التنسيق والتفاعل المشترك.</p><a class="nq-button secondary" href="downloads/marketing.html" download>تحميل أمثلة التسويق ↓</a>`)}
function patterns(){return head('patterns','ثلاث تركيبات توضح كيف تصبح الأسس منتجًا: محادثة، بحث، ولوحة استخدام. كل البيانات هنا توضيحية ومحلية.')+section('chat','المحادثة / Chat',preview(`<div class="demo-chat"><div class="row between"><b>✦ مساعد نسق</b><span class="nq-badge">عرض محلي</span></div><div id="chat-log" role="log" aria-live="polite"><div class="chat-message"><b>نسق</b><p>أهلًا. بماذا تفكّر اليوم؟ جرّب أن تطلب مسودة أو تلخيصًا.</p></div></div><form id="chat-form" class="composer"><label class="sr-only" for="chat-prompt">رسالتك إلى المساعد</label><input id="chat-prompt" class="nq-input" placeholder="اكتب فكرتك…" required maxlength="500"><button class="nq-button" type="submit">إرسال ←</button></form><p class="nq-help">مثال تصميم. الردود ثابتة ولا يتصل بنموذج ذكاء اصطناعي.</p></div>`))+section('search','البحث / Search',preview('<label for="knowledge-search">ابحث في المعرفة</label><input id="knowledge-search" class="nq-input" type="search" placeholder="اكتب: كتابة، بحث، مشروع…"><div id="knowledge-results" class="document-list" style="margin-top:16px"></div>'))+section('dashboard','الاستخدام / Dashboard',preview('<span class="nq-badge">بيانات توضيحية</span><div class="data-stats" style="margin-top:16px"><div class="data-stat"><span>المحادثات</span><b>128</b></div><div class="data-stat"><span>المستندات</span><b>24</b></div><div class="data-stat"><span>المتبقي من الحصة</span><b>72%</b></div></div><figure style="margin:0"><div class="bars" aria-hidden="true">'+[30,55,40,75,62,90,68].map(n=>`<i style="height:${n}%"></i>`).join('')+'</div><figcaption class="nq-help">المحادثات خلال أسبوع: 12، 22، 16، 30، 25، 36، 27. بيانات مثال وليست تحليلات فعلية.</figcaption></figure>'))+section('behavior','حالات AI الضرورية',table(['الحالة','ما يراه المستخدم','الإجراء'],[['Empty','سؤال بداية واقتراحات واضحة','بدء محادثة'],['Generating','نص: جاري إعداد الرد + زر إيقاف','إيقاف دون فقد الإدخال'],['Error','تعذر الاتصال. احتفظنا برسالتك.','إعادة المحاولة'],['Sources','قائمة مصادر قابلة للفتح','مراجعة الدليل'],['Quota','حصة الاستخدام المتبقية','شرح قبل منع الطلب']])+`<p class="note">هذه قواعد تكامل للمنتج الفعلي. العرض المحلي يحاكي ردًا ثابتًا؛ لا يعرض توليدًا أو مصادر مزعومة.</p>`)}
function start(){return head('start','ابدأ بالملفات الجاهزة. نسق مستقل عن إطار العمل، ويمكن تطبيقه على HTML أو React أو Vue أو أي واجهة ويب.')+section('install','١. أضف الملفات',`<p>نزّل الحزمة وفك الضغط. احتفظ بملفات الخطوط داخل assets بجوار nasaq.css؛ الملفات تعمل دون خدمة خطوط خارجية.</p><a class="nq-button" href="downloads/nasaq-system.zip" download>تحميل الحزمة ↓</a>`+code('<link rel="stylesheet" href="nasaq.css">\n<script src="nasaq.js" defer></script>\n<html lang="ar" dir="rtl">\n  <body class="nq">…</body>\n</html>'))+section('build','٢. ابنِ من المكونات',code('<main class="nq" dir="rtl">\n <h1 style="font-family:var(--nq-font-display)">بماذا تفكّر اليوم؟</h1>\n <label for="idea">فكرتك</label>\n <input id="idea" class="nq-input" placeholder="اكتب سطرًا…">\n <button class="nq-button">ابدأ المحادثة</button>\n</main>')+`<p>استخدم <a class="tag-link" href="#buttons">مكونات نسق الثمانية عشر</a> و<a class="tag-link" href="#marketing">تركيبات التسويق</a>. التفاعل المشترك متاح في nasaq.js؛ منطق المنتج يبقى في تطبيقك.</p>`)+section('design','٣. للمصممين',`<p>ملف tokens.json يفصل القيم الأساسية عن الأدوار الدلالية ووضعي Light/Dark. الألوان بصيغة DTCG؛ يمكن تحويلها عبر أدوات تدعم هذه الصيغة. هذه الحزمة لا تتضمن مكتبة Figma أصلية.</p>`+table(['المجموعة','الاستخدام'],[['Primitives','Color / Space / Radius / Type / Motion'],['Semantic · Light / Dark','Background / Surface / Text / Border / Action / Link'],['Components','اربط المكونات بالأدوار الدلالية، لا بقيم HEX مباشرة']]))+section('review','٤. راجع التجربة',`<p>افحص العربية والتشكيل والمحتوى المختلط، 360px للجوال، التركيز المرئي، لوحة المفاتيح، وتباين النص. مهارة نسق المرفقة تساعد مساعدك على تطبيق القواعد نفسها.</p><a class="nq-button secondary" href="#skill">استخدام مهارة AI ↖</a>`)}
