function skill(){return head('skill','ملف تعليمات قابل للإرفاق لمساعدك. يشرح الهوية، القيم، المكونات، وقواعد تحويل واجهة موجودة إلى نسق.')+section('attach','أرفق. اطلب. راجع.',`<div class="skill-banner"><div><span class="eyebrow">NASAQ · UI SKILL</span><h2>نظام كامل، يفهمه مساعدك.</h2><p>مهارة مستقلة مع CSS وأيقونات وخطوط ومراجع للقواعد.</p></div><a class="nq-button" href="downloads/nasaq-ui-skill.zip" download>تحميل المهارة ↓</a></div>`)+section('prompt','طلب جاهز',code('استخدم مهارة Nasaq المرفقة لتحويل واجهتي إلى نظام نسق.\nحافظ على الوظائف والمحتوى، وطبّق RTL والخطوط والمتغيرات والمكونات.\nراجع حالات التركيز والخطأ والتعطيل، ثم اعرض النتيجة وما يحتاج إلى تحقق.')+`<p>أرفق الحزمة كاملة عندما يستطيع مساعدك قراءة الملفات. إذا كان يدعم إرفاق نص فقط، أرفق SKILL.md؛ يتضمن القيم الأساسية، لكن الخطوط والأصول تحتاج الحزمة.</p><a class="nq-button secondary" href="downloads/nasaq-ui/SKILL.md" download>SKILL.md فقط ↓</a>`)+section('scope','ما تغطيه المهارة',table(['القسم','التعليمات'],[['Design direction','حبر وورق، أحمر حيوي، عناوين نسخية، تنظيم تحريري'],['Tokens','مراجع CSS وJSON، Light/Dark'],['Components','اختيار المكوّن، الحالات، والتسمية'],['RTL & accessibility','خصائص منطقية، عزل الكود، التركيز والملاحة'],['Workflow','مراجعة الواجهة → تطبيق → تحقق → تسليم']]))+section('limitations','حدود واضحة',`<p>المهارة توجه المساعد ولا تضمن نتيجة مطابقة دون مراجعة. لا تغيّر الوظائف أو تضف اتصال AI أو تحليلات أو دفعًا لمجرد تطبيق الهوية. القيم والنسخ توضيحية؛ اختبرها في سياق منتجك.</p>`)}
function downloads(){return head('downloads','كل ما تحتاجه لتصميم واجهة بنسق واحد. ملفات حقيقية، جاهزة للنسخ والاستخدام.')+section('files','ملفات النظام',`<div class="document-list">${[['nasaq-ui-1.3.0.tgz','حزمة npm','@nasaq/ui · CSS + JS + TypeScript · AR / EN'],['components-en.html','أمثلة المكونات بالإنجليزية','English HTML · LTR'],['motion-en.html','الحركة بالإنجليزية','English motion demos'],['nasaq-lucide-icons.zip','مكتبة Lucide','2130 SVG + license + manifest'],['motion.html','الحركة والتفاعل','Standalone interactive examples'],['nasaq-brand-kit.zip','حزمة الهوية','SVG + Templates + Brand guidelines'],['nasaq-mcp.zip','خادم MCP','Local stdio server + catalog + setup'],['nasaq-system.zip','الحزمة الكاملة','CSS + JS + Tokens + Fonts + SVG + Examples'],['nasaq-ui-skill.zip','مهارة نسق','SKILL.md + References + Assets'],['tokens.json','المتغيرات','DTCG JSON · Light / Dark'],['nasaq.css','أنماط الواجهة','CSS variables + 18 components'],['nasaq.js','التفاعل المشترك','Tabs + Dialog + Tooltip'],['components.html','أمثلة المكونات','Standalone HTML'],['marketing.html','أمثلة التسويق','Standalone HTML']].map(x=>`<a href="downloads/${x[0]}" download><span><b>${x[1]}</b><small style="display:block;color:var(--nq-muted);font:11px Arial">${x[2]}</small></span><span>↓</span></a>`).join('')}</div>`)+section('case','دراسة المشروع',`<p>صفحة مستقلة، تركز على الهوية والتطبيقات والمكونات. جاهزة للنقل إلى بورتفوليو مع مجلد assets.</p><a class="nq-button secondary" href="case-study.html">افتح الدراسة ↗</a> <a class="nq-button secondary" href="downloads/nasaq-case-study.zip" download>تحميل ملفات الدراسة ↓</a>`)+section('license','المصدر والتراخيص',`<p>هوية نسق ومكوناته ورموزه أصلية لهذا المشروع. أضيفت مكتبة Lucide مفتوحة المصدر مع ترخيصها، وتبقى أيقونات نسق الأصلية منفصلة. مستوحاة من الاتجاه البصري لثمانية، دون استخدام شعارها أو أصولها أو خطوطها الخاصة. الخطوط مفتوحة المصدر مع التراخيص المرفقة.</p><p>مرجع الهوية: <a class="tag-link" href="https://www.behance.net/gallery/192657457/Thmanyah" target="_blank" rel="noopener">Thmanyah — Milk Network</a>. مرجع التركيبات التحريرية: <a class="tag-link" href="https://thmanyah.com/" target="_blank" rel="noopener">موقع ثمانية</a>.</p>`)}
