const extraComponents={
radio:{desc:'اختيار واحد من بدائل متعارضة. يبدأ الاختيار من قرار واضح، لا افتراض خفي.',html:'<fieldset class="nq-radio-group"><legend>أسلوب المساعد</legend><label class="nq-check"><input type="radio" name="assistant-tone" checked> مباشر</label><label class="nq-check"><input type="radio" name="assistant-tone"> تفصيلي</label><label class="nq-check"><input type="radio" name="assistant-tone" disabled> مخصص — غير متاح</label></fieldset>',snippet:'<fieldset class="nq-radio-group">\n <legend>أسلوب المساعد</legend>\n <label class="nq-check"><input type="radio" name="tone" value="direct" checked> مباشر</label>\n <label class="nq-check"><input type="radio" name="tone" value="detailed"> تفصيلي</label>\n</fieldset>',rule:'استخدم name مشتركًا. التنقل بالأسهم أصلي؛ Space يختار. لا تستخدم radio لتنفيذ إجراء.'},
textarea:{desc:'أفكار أطول، مع تسمية واضحة ومساحة تتمدد عموديًا.',html:'<div class="nq-field"><label for="long-prompt">تعليمات المساعد</label><textarea id="long-prompt" class="nq-input nq-textarea" rows="4" maxlength="500" aria-describedby="long-help" placeholder="اشرح المطلوب والجمهور والأسلوب…"></textarea><span id="long-help" class="nq-help">حتى 500 حرف. لا تُرسل هذه المسودة.</span></div>',snippet:'<label for="prompt">تعليمات المساعد</label>\n<textarea id="prompt" class="nq-input nq-textarea" rows="4" maxlength="500" aria-describedby="prompt-help"></textarea>\n<p id="prompt-help" class="nq-help">حتى 500 حرف.</p>',rule:'احتفظ بالمسودة عند الفشل. لا تمنع تغيير الحجم عموديًا؛ اعرض الحد قبل الإدخال.'},
alert:{desc:'رسالة في سياقها: ماذا حدث، وماذا يمكن أن يفعل المستخدم.',html:'<div class="nq-alert success"><b>تم حفظ المسودة.</b><p>يمكنك العودة إليها من المشروع.</p></div><div class="nq-alert error" style="margin-top:16px"><b>تعذر الاتصال.</b><p>احتفظنا برسالتك. حاول مرة أخرى.</p><button class="nq-button secondary" data-toast="مثال محلي لإعادة المحاولة">إعادة المحاولة</button></div>',snippet:'<div class="nq-alert error" role="alert">\n <b>تعذر الاتصال.</b><p>احتفظنا برسالتك.</p>\n <button class="nq-button secondary">إعادة المحاولة</button>\n</div>',rule:'استخدم role=alert لخطأ جديد يحتاج الانتباه. الرسائل الثابتة لا تحتاج إعلانًا متكررًا.'},
progress:{desc:'حصة أو مهمة ذات تقدم معلوم. الرقم يشرح الشريط ولا يدّعي دقة غير متاحة.',html:'<label for="usage-progress">الحصة المستخدمة — 28%</label><progress id="usage-progress" class="nq-progress" max="100" value="28">28%</progress><label for="upload-progress">تقدم غير محدد — جارٍ الرفع</label><progress id="upload-progress" class="nq-progress">جارٍ الرفع</progress>',snippet:'<label for="usage">الحصة المستخدمة — 28%</label>\n<progress id="usage" class="nq-progress" max="100" value="28">28%</progress>',rule:'لا تستخدم رقمًا مزيفًا لتوليد AI. احذف value للتقدم غير المحدد، ووفّر نص حالة.'},
skeleton:{desc:'مكان محجوز للمحتوى الذي سيصل. يبقى شكل الصفحة مستقرًا أثناء التحميل.',html:'<div aria-busy="true" aria-label="جارٍ تحميل بطاقة المشروع"><div class="nq-skeleton" style="width:44px;height:44px;border-radius:50%"></div><div class="nq-skeleton" style="width:65%;margin-top:16px"></div><div class="nq-skeleton" style="width:90%;margin-top:8px"></div><span class="nq-help">جارٍ تحميل المشروع…</span></div>',snippet:'<section aria-busy="true" aria-label="جارٍ التحميل">\n <div class="nq-skeleton" aria-hidden="true"></div>\n <span class="nq-help">جارٍ تحميل المشروع…</span>\n</section>',rule:'أزل aria-busy بعد وصول المحتوى. لا تحول الخطأ إلى تحميل دائم؛ اعرض رسالة وإعادة المحاولة.'},
accordion:{desc:'تفاصيل عند الطلب. summary أصلي يعمل بلوحة المفاتيح ويفصح عن حالته.',html:'<div class="nq-faq"><details open><summary>كيف تُحفظ المحادثة؟</summary><p>هذا وصف تصميمي. يحدد منتجك الفعلي مدة الحفظ وإعداداته.</p></details><details><summary>كيف أحذف البيانات؟</summary><p>اعرض مسارًا واضحًا للحذف مع تأكيد مناسب.</p></details></div>',snippet:'<div class="nq-faq">\n <details><summary>كيف يعمل؟</summary><p>تفاصيل واضحة.</p></details>\n</div>',rule:'لا تخفِ معلومات مطلوبة لاتخاذ القرار. استخدم details مستقلًا؛ لا حاجة إلى ARIA إضافي.'},
cards:{desc:'وحدة محتوى قابلة للمقارنة، مع عنوان وفعل واضح دون تحويل كل شيء إلى رابط.',html:'<article class="nq-card"><span class="nq-badge">مساعد</span><h3>مساعد الكتابة</h3><p>مسودة أقرب إلى أسلوبك.</p><button class="nq-button secondary" data-toast="مثال محلي لبطاقة المساعد">استكشف المساعد</button></article>',snippet:'<article class="nq-card">\n <h3>مساعد الكتابة</h3><p>مسودة أقرب إلى أسلوبك.</p>\n <a class="nq-button secondary" href="/assistant/writing">استكشف المساعد</a>\n</article>',rule:'لا تضمّن روابط داخل رابط يغطي البطاقة. استخدم عنوانًا دلاليًا وترتيب قراءة طبيعيًا.'},
breadcrumb:{desc:'سياق الصفحة داخل المشروع. الصفحة الحالية نص واضح ولا تحتاج رابطًا إلى نفسها.',html:'<nav class="nq-breadcrumb" aria-label="مسار التنقل"><a href="#overview">نسق</a><span aria-hidden="true">/</span><a href="#patterns">المشاريع</a><span aria-hidden="true">/</span><span aria-current="page">مشروع الكتابة</span></nav>',snippet:'<nav class="nq-breadcrumb" aria-label="مسار التنقل">\n <a href="/">الرئيسية</a><span aria-hidden="true">/</span>\n <span aria-current="page">المشروع</span>\n</nav>',rule:'اختصر المسار على الهاتف دون حذف الصفحة الحالية. لا تعكس DOM لتغيير الاتجاه.'}
};
Object.entries(extraComponents).forEach(([id,e])=>{e.props=[['state',id==='radio'?'unchecked / checked / focus / disabled':id==='alert'?'info / success / warning / error':id==='progress'?'empty / active / complete / indeterminate':id==='accordion'?'collapsed / expanded / focus':id==='skeleton'?'loading / reduced motion / loaded / error':id==='cards'?'default / hover / focused action / empty / loading':id==='breadcrumb'?'default / focused link / current / compact':'default / focus / disabled / error','راجع الأمثلة المرئية أدناه'],['direction','RTL / LTR','خصائص CSS منطقية']];examples[id]=e});
