const basePatterns=patterns;
patterns=function(){return basePatterns().replace('ثلاث تركيبات','اثنتا عشرة تركيبة')+patternExtras.map(([id,title,h,rule])=>section(id,title,preview(h)+`<p class="note">${rule}</p>`)).join('')};
function brand(){return head('brand','هوية نسق في حزمة واحدة: الشعار، الألوان، الخط، الرموز، ونبرة الصوت. ملفات SVG قابلة للتحرير وقوالب للبدء.')+section('kit','حزمة الهوية',`<div class="brand-board"><div class="brand-lockup">${mark}<b>نسق</b><small>NASAQ</small></div><div class="brand-voice"><span class="eyebrow">CLEAR · HUMAN · ARABIC</span><h2>فكرة واضحة.<br>وحضور له نسق.</h2></div></div><div class="row" style="margin-top:24px"><a class="nq-button" href="downloads/nasaq-brand-kit.zip" download>تحميل Brand kit ↓</a><a class="nq-button secondary" href="downloads/brand-kit/brand-guide.html">دليل الهوية ↗</a></div>`)+section('assets','الأصول',`<div class="document-list">${[['mark-ink.svg','رمز الحبر'],['mark-paper.svg','رمز الورق'],['lockup-horizontal.svg','تركيب أفقي'],['lockup-stacked.svg','تركيب عمودي'],['social-card.svg','قالب مشاركة 1200×630'],['avatar.svg','صورة رمزية 512×512'],['palette.json','ألوان الهوية JSON']].map(([f,n])=>`<a href="downloads/brand-kit/${f}" download><b>${n}</b><small dir="ltr">${f} ↓</small></a>`).join('')}</div>`)+section('voice','نبرة الصوت',table(['اكتب','بدلًا من'],[['ابدأ محادثة','فعّل قدرات الذكاء الاصطناعي'],['تعذر الحفظ. حاول مجددًا.','حدث خطأ غير متوقع 500'],['لا ملفات بعد. أضف ملفك الأول.','لا توجد بيانات']])+`<p>واضح، إنساني، عربي. لا نبالغ في وعود AI، ولا نستخدم مصطلحات تقنية عندما تكفي كلمة مألوفة.</p>`)+section('rules','قواعد الهوية',table(['العنصر','القاعدة'],[['الشعار','خمس وحدات، دون ميل أو تمدد أو ظل'],['مساحة خالية','¼ عرض الرمز من كل جهة'],['الحد الأدنى','24px رمز / 100px تركيب'],['الخط','Almarai 300 / 400 / 700 / 800'],['التسويق','ورق ومينت ولافندر ووردي؛ نص حبر'],['التعبير','رمز هندسي واحد لكل لوحة']])+`<p class="nq-help">تركيبات SVG تحتوي نصًا حيًا وخط Almarai مضمّنًا للعرض. عند التحرير في برنامج لا يدعم الخط المضمّن، ثبّت الخطوط المرفقة. الرمز مستقل عن الخط.</p>`)}
async function tokens(){return head('tokens','نبني القيم من أساس ثابت إلى معنى، ثم إلى مكوّن. هذه البنية مستلهمة من وضوح قواعد الملف المرجعي، مع هوية نسق وقيمه الأصلية.')+section('architecture','كيف تُبنى المتغيرات؟',`<div class="token-flow"><div><small>01 · PRIMITIVE</small><b>color.ink</b><code>#171717</code><p>قيمة خام؛ لا تصف استخدامها.</p></div><div><small>02 · SEMANTIC</small><b>semantic.light.action</b><code>{color.ink}</code><p>معنى في المظهر الحالي.</p></div><div><small>03 · COMPONENT</small><b>component.button.light.background</b><code>{semantic.light.action}</code><p>قرار متكرر داخل المكوّن.</p></div></div><p>النمط يجمع المكونات، ولا يكرر القيم. تغيير color.ink ينتقل عبر المراجع. تغيير مظهر الصفحة يبدّل الأدوار والأسماء تبقى ثابتة.</p>`+code('component.button.light.background → semantic.light.action → color.ink\ncomponent.button.dark.background  → semantic.dark.action  → color.paper\ncomponent.card.padding → space.24\ncomponent.switch.width → space.48'))+section('naming','الاسم، النوع، والقيمة',table(['المستوى','اسم JSON','CSS'],[['Primitive','space.24','--nq-space-24'],['Semantic','semantic.light.text','--nq-text'],['Component','component.button.light.background','--nq-component-button-background']])+code(JSON.stringify({'$type':'color','$value':'{semantic.light.action}','$description':'Primary button background in light mode.'},null,2))+`<p>$type يحدد نوع القيمة. $value قيمة أو مرجع بين أقواس. $description يشرح القرار. الأسماء تصف الدور، لا شاشة مؤقتة أو لونًا ضمن اسم مكوّن.</p>`)+section('build','من JSON إلى الواجهة',`<ol><li>عدّل downloads/tokens.json، مصدر القيم المعتمد.</li><li>شغّل <bdi dir="ltr">python3 scripts/build.py</bdi> من مجلد Nasaq.</li><li>يفحص البناء المراجع والدورات والأنواع، ويولد المتغيرات والمظهرين.</li><li>تتزامن CSS ونسخة المهارة وبيانات التوثيق وحزم ZIP.</li><li>راجع التباين وحالات المكونات بصريًا قبل اعتماد تغيير الهوية.</li></ol>`+code('cd Nasaq\npython3 scripts/build.py\npython3 scripts/verify.py')+`<p>مثل الملف المرجعي، نفصل الأسطح والنصوص والحدود والتأثيرات حسب الدور والمظهر. لا ننقل ألوان FDS أو قواعد عروضه إلى نسق. المرجع ليس تعليمة لتغيير نطاق مشروعك.</p><a class="tag-link" href="https://www.designtokens.org/tr/2025.10/format/" target="_blank" rel="noopener">مواصفة DTCG Format 2025.10 ↗</a>`)+section('explorer','مستكشف المتغيرات',`<div class="token-toolbar"><input id="token-filter" class="nq-input" type="search" placeholder="ابحث: component، semantic، effect…" aria-label="تصفية المتغيرات"><span id="token-count" class="nq-help"></span></div><div id="token-table">جاري تحميل المتغيرات…</div><div class="row"><a class="nq-button secondary" href="downloads/tokens.json" download>DTCG JSON ↓</a><a class="nq-button secondary" href="downloads/nasaq.css" download>CSS ↓</a></div>`)}
function aiGuide(){return head('ai-guide','حوّل نسق من مرجع بصري إلى جزء من سير عمل مشروعك. استخدم المهارة للتوجيه وMCP للوصول إلى التعريفات الحقيقية.')+section('choose','اختر طريقة الاستخدام',table(['الطريقة','متى تستخدمها','ما تحتاجه'],[['Skill','تطبيق الهوية على واجهة أو إعادة تنسيق مشروع','الحزمة وفك الضغط وSKILL.md'],['MCP','استرجاع المكونات والمتغيرات حسب المهمة','عميل يدعم stdio + Python 3.10+'],['Direct files','تكامل يدوي أو إطار خاص','nasaq.css + fonts + native behavior']]))+section('workflow','من الفكرة إلى التنفيذ',`<ol><li>أرفق SKILL.md أو اطلب من مساعدك قراءته مع references وassets.</li><li>اذكر الإطار، الشاشة المطلوبة، المحتوى، والوظائف التي يجب الحفاظ عليها.</li><li>اطلب اختيار المكونات والأنماط قبل التنفيذ.</li><li>طبّق المتغيرات الدلالية بدل قيم ألوان عشوائية.</li><li>راجع RTL والنص المختلط ولوحة المفاتيح والمظهرين والهاتف.</li></ol>`)+section('prompt','طلب جاهز لمشروعك',code('طبّق نظام نسق على شاشة المحادثة في مشروعي.\nاقرأ nasaq-ui/SKILL.md والمراجع المرفقة أولًا.\nالإطار: [React / Vue / HTML]. اللغة: العربية، RTL، والخط Almarai.\nحافظ على المسارات والبيانات والمنطق الحالي.\nاستخدم متغيرات نسق ومكوناته، مع حالات فارغة وتحميل وخطأ.\nللتسويق استخدم الورق والمينت واللافندر مع نص حبر.\nلا تخترع ردود AI أو مصادر أو بيانات تجارية.\nنفّذ ثم اختبر التفاعل ولوحة المفاتيح وراجع الهاتف والمظهر الداكن.'))+section('mcp-workflow','عند الاتصال بـ MCP',code('1. search_nasaq({query:"switch"})\n2. get_component({id:"switch"})\n3. get_tokens({prefix:"component.switch"})\n4. get_guidelines({section:"skill"})')+`<p>يعيد الخادم HTML والحالات والقواعد والأصول. مساعدك يطبّقها في مشروعك بحسب الإطار. الخادم نفسه لا يحرّر ملفاتك ولا يستدعي نموذج AI.</p><a class="nq-button secondary" href="#mcp">إعداد MCP ↖</a>`)+section('product-ai','ربط المنتج بنموذج فعلي',`<p>أمثلة الموقع محلية. اربط API من خادم مشروعك، واحتفظ بالمفاتيح خارج المتصفح. اربط الإرسال والتوليد والإيقاف والفشل والمصادر ببيانات حقيقية. استعمل حالات نسق لكل نتيجة، دون تغيير مضمون المستخدم.</p><div class="nq-alert"><b>قبل التسليم</b><p>الإرسال لا يتكرر، المسودة لا تضيع، الإيقاف يعمل، المراجع حقيقية، الأخطاء قابلة للاسترداد، والحصة واضحة قبل الطلب.</p></div>`)}
function mcp(){const config={mcpServers:{nasaq:{command:'python3',args:['/ABSOLUTE/PATH/nasaq-mcp/server.py']}}};return head('mcp','خادم MCP محلي جاهز للتوصيل. يتيح لمساعدك قراءة المتغيرات والمكونات والحالات والأنماط والهوية من ملفات نسق الفعلية.')+section('connect','التوصيل',`<ol><li>حمّل nasaq-mcp.zip وفك الضغط. لا يلزم تثبيت حزم إضافية.</li><li>تأكد من وجود Python 3.10 أو أحدث.</li><li>في إعدادات عميل يدعم MCP stdio، أضف الخادم بالمسار المطلق إلى server.py.</li><li>أعد تحميل العميل، ثم اطلب منه البحث عن switch أو قراءة متغيرات نسق.</li></ol><a class="nq-button" href="downloads/nasaq-mcp.zip" download>تحميل خادم MCP ↓</a>`+code(JSON.stringify(config,null,2))+`<p class="nq-help">هذا مثال إعداد عام؛ غيّر المسار حسب مكان فك الحزمة. بعض العملاء يستخدمون صيغة إعداد أخرى. الاتصال المحلي يحتاج تشغيلًا على الجهاز؛ ليس عنوان MCP مستضافًا.</p>`)+section('tools','الأدوات',table(['Tool','المدخل','النتيجة'],[['search_nasaq','query','بحث في المكونات والأنماط والأصول والمتغيرات'],['get_component','id','HTML + states + props + rules'],['get_tokens','prefix (optional)','Typed tokens + resolved values'],['get_pattern','id','مثال HTML + قواعد تكامل'],['get_guidelines','section','skill / brand / tokens / ai / motion / typography / colors'],['get_asset','name','نص SVG / CSS أو معلومات خط مع مساره']]))+section('resources','Resources & prompts',`<p>الموارد: <bdi dir="ltr">nasaq://tokens</bdi>، <bdi dir="ltr">nasaq://catalog</bdi>، <bdi dir="ltr">nasaq://skill</bdi>، <bdi dir="ltr">nasaq://brand</bdi>، <bdi dir="ltr">nasaq://motion</bdi>. الطلب الجاهز <bdi dir="ltr">apply_nasaq</bdi> يقبل وصف المهمة. يعلن الخادم قدراته خلال initialize.</p>`)+section('boundaries','حدود التكامل',`<p>الخادم للقراءة فقط، لا شبكة ولا مفاتيح API ولا تعديل ملفات المشروع. يدعم نقل stdio وإصدار البروتوكول 2025-06-18؛ لا يحتاج خدمة خارجية.</p><a class="tag-link" href="https://modelcontextprotocol.io/specification/2025-06-18/basic/transports" target="_blank" rel="noopener">مواصفة نقل MCP ↗</a>`)}

const foundationTokens=globalThis.NASAQ_TOKENS||{},lucideIcons=globalThis.NASAQ_ICONS||[];
function resolveFoundation(path){let node=path.split('.').reduce((o,k)=>o?.[k],foundationTokens);function value(v){if(typeof v==='string'&&v.startsWith('{')&&v.endsWith('}'))return resolveFoundation(v.slice(1,-1));if(Array.isArray(v))return v.map(value);if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,value(x)]));return v}return value(node?.$value)}
function onColor(hex){function lum(h){const v=[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)/255).map(n=>n<=.04045?n/12.92:((n+.055)/1.055)**2.4);return v[0]*.2126+v[1]*.7152+v[2]*.0722}return (lum(hex)+.05)/(lum('#171717')+.05)>=4.5?'#171717':1.05/(lum(hex)+.05)>=4.5?'#FFFFFF':'#000000'}
const baseColors=colors;
colors=function(){return baseColors()+section('shades','درجات اللون / 8 × 11',`<p>٨ عائلات، من 50 إلى 950. الدرجة تعبّر عن العمق، وليست ضمانًا للتباين. اختر دورًا دلاليًا أولًا، ثم اختبر النص والخلفية معًا.</p><div class="shade-families">${Object.entries(foundationTokens.shade||{}).map(([name,steps])=>`<article class="shade-family"><h3 dir="ltr">${name}</h3><div class="shade-ramp">${Object.entries(steps).map(([step,t])=>`<button class="shade-step" style="background:${t.$value.hex};color:${onColor(t.$value.hex)}" data-copy="${t.$value.hex}" aria-label="نسخ ${name} ${step}: ${t.$value.hex}"><b>${step}</b><small>${t.$value.hex}</small></button>`).join('')}</div><p class="nq-help" dir="ltr">shade.${name}.{50…950} · --nq-shade-${name}-{50…950}</p></article>`).join('')}</div>`)+section('shade-roles','من الدرجة إلى الدور',code('/* Assign meaning; do not rename colors per screen. */\n:root { --project-info-surface:var(--nq-shade-blue-50);\n        --project-info-text:var(--nq-shade-blue-900); }\n[data-theme="dark"] {\n --project-info-surface:var(--nq-shade-blue-950);\n --project-info-text:var(--nq-shade-blue-100);\n}')+`<p>الدرجات الجديدة لا تغيّر ألوان نسق الدلالية تلقائيًا. المحايد للمحتوى والأسطح، الأخضر للنجاح، الأزرق للمعلومات، والألوان المساعدة للتجميع. تبقى خلفيات التسويق فاتحة؛ لا نعيد المقدمة الحمراء الكبيرة.</p>`)};
const typeLabels={'display-lg':'بيان كبير','display-md':'بيان متوسط','display-sm':'بيان مدمج','heading-xl':'عنوان الصفحة','heading-lg':'عنوان القسم','heading-md':'عنوان البطاقة','heading-sm':'عنوان فرعي','body-lg':'نص تمهيدي','body-md':'النص الأساسي','body-sm':'نص ثانوي','body-light':'نص تحريري خفيف','label-lg':'تسمية كبيرة','label-sm':'تسمية مدمجة','caption':'تعليق ومساعدة','overline':'تصنيف','button':'نص الإجراء','quote':'اقتباس','data':'بيانات وأرقام','code':'كود تقني'};
const typeSamples={'display-lg':'فكرة تستحق مساحة.','display-md':'المعرفة، أقرب.','display-sm':'من هنا تبدأ الفكرة.','heading-xl':'عنوان صفحة واضح.','heading-lg':'تفاصيل لها معنى.','heading-md':'ابدأ من الأساس.','heading-sm':'مساحة العمل','body-lg':'المعرفة أقرب عندما تكون اللغة واضحة.','body-md':'اكتب فكرتك، ودع التفاصيل تأخذ مكانها.','body-sm':'آخر تحديث للمشروع قبل قليل.','body-light':'مساحة هادئة لقراءة أطول.','label-lg':'اسم المشروع','label-sm':'إعدادات المحادثة','caption':'بيانات توضيحية — لا توجد عملية إرسال.','overline':'نظام تصميم عربي','button':'ابدأ محادثة','quote':'كل فكرة تستحق أن تُقال.','data':'128 / ٧٢٪','code':'const theme = "nasaq";'};
function typography(){return head('typography','المراعي هو الخط الرئيسي. ١٩ أسلوبًا طباعيًا يغطّي العناوين والقراءة والواجهات والبيانات، بأوزان حقيقية دون تباعد حروف العربية.')+section('font','Almarai / الخط الرئيسي',preview(`<div class="type-weight-grid">${[300,400,700,800].map(w=>`<div><small dir="ltr">Almarai ${w}</small><p style="font-weight:${w};font-size:28px;line-height:1.8">لكل حرف، مساحته.</p></div>`).join('')}</div>`)+`<p>الخط مرفق محليًا تحت SIL OFL. الأوزان: 300 / 400 / 700 / 800. لا تُركّب وزن 500 أو 600 اصطناعيًا. الخط أحادي المسافة مخصص للكود الإنجليزي فقط.</p>`)+section('styles','مكتبة الأساليب',`<div class="type-style-list">${Object.entries(foundationTokens.type||{}).map(([name,t])=>{const v=resolveFoundation('type.'+name);return `<article class="type-style"><div class="type-style-meta"><b>${typeLabels[name]}</b><small dir="ltr">${name} · ${v.fontSize.value}px / ${v.fontWeight} / ${v.lineHeight}</small><button data-copy="nq-type-${name}" aria-label="نسخ فئة ${name}">Class ⧉</button></div><div class="nq-type-${name}" ${name==='code'?'dir="ltr"':''}>${typeSamples[name]}</div></article>`}).join('')}</div>`)+section('responsive-type','التدرّج المتجاوب',table(['Style','Desktop','Mobile ≤ 640px'],[['display-lg','72px / 800','44px / 800'],['display-md','64px / 800','40px / 800'],['display-sm','48px / 700','36px / 700'],['heading-xl','40px / 700','32px / 700'],['heading-lg','32px / 700','28px / 700'],['Body','16–20px / 1.8','يبقى مقروءًا، دون تصغير تلقائي']])+`<p>أساليب display اختيارية للمواد التحريرية، لا مقدمة افتراضية لكل شاشة. يمكن استخدام عنوان 32–40px دون لوحة لونية كبيرة.</p>`)+section('composition','تركيب يحافظ على القراءة',preview('<article style="max-width:65ch"><span class="nq-type-overline">دليل الكتابة</span><h3 class="nq-type-heading-lg">حين تجد الفكرة كلماتها.</h3><p class="nq-type-body-lg">مسودة واضحة تبدأ بسؤال واضح، ثم ترتيب يترك مساحة للمعنى.</p><p class="nq-type-body-md">اكتب للقارئ، لا للمصطلح. استخدم جملًا مباشرة، واترك ارتفاع السطر مريحًا للتشكيل. هذا نص مثال لتوضيح الإيقاع الطباعي.</p><p class="nq-type-caption">وقت القراءة: ٣ دقائق · مثال توضيحي</p></article>')+code('<h1 class="nq-type-heading-xl">عنوان الصفحة</h1>\n<p class="nq-type-body-md">النص الأساسي.</p>\n<!-- type.body-md is a DTCG typography composite. -->'))+section('bidi','العربية والتشكيل والمحتوى المختلط',preview('<p class="nq-type-body-lg">نَسَقٌ واضحٌ، وتجربةٌ أَقربُ.</p><p>راسلنا على <bdi dir="ltr">hello@example.com</bdi> · <bdi dir="ltr">NASAQ-2026</bdi></p>')+`<p>لا تستخدم letter-spacing للعربية أو ارتفاعًا ثابتًا يقصّ التشكيل. اعزل البريد والروابط والكود بـ bdi. فئة البيانات تستخدم أرقامًا جدوليّة حيث يدعمها الخط؛ تحقق من الأرقام العربية الفعلية في منتجك.</p>`)}
function icons(){return head('icons','مكتبة Lucide مفتوحة المصدر، مرفقة محليًا دون خدمة خارجية، إلى جانب أيقونات نسق الأصلية. ابحث بالاسم أو المهمة ثم حمّل SVG أو انسخ مساره.')+section('lucide','Lucide / '+lucideIcons.length+' SVG',`<div class="icon-browser"><div class="icon-toolbar"><label for="lucide-search" class="sr-only">البحث في أيقونات Lucide</label><input id="lucide-search" class="nq-input" type="search" placeholder="ابحث: search، bot، folder، بحث…"><label for="lucide-category" class="sr-only">مجموعة الأيقونات</label><select id="lucide-category" class="nq-select"><option value="all">كل الأيقونات</option><option value="ai">AI ومحادثة</option><option value="navigation">تنقل وأفعال</option><option value="files">ملفات ومشاريع</option><option value="data">بيانات ولوحات</option><option value="media">وسائط وصوت</option><option value="commerce">اشتراك وفريق</option></select><label for="lucide-size" class="sr-only">حجم المعاينة</label><select id="lucide-size" class="nq-select"><option value="24">24px</option><option value="20">20px</option><option value="32">32px</option></select></div><p id="lucide-count" class="nq-help" role="status"></p><div id="lucide-grid" class="icon-grid lucide-grid">${lucideCells(lucideIcons.slice(0,72))}</div><button id="lucide-more" class="nq-button secondary" type="button">عرض المزيد</button></div><div class="row" style="margin-top:24px"><a class="nq-button secondary" href="downloads/nasaq-lucide-icons.zip" download>تحميل المكتبة كاملة ↓</a><a class="tag-link" href="assets/lucide/LICENSE">الترخيص المرفق</a><a class="tag-link" href="https://lucide.dev/license" target="_blank" rel="noopener">Lucide license ↗</a></div><p class="nq-help">Lucide Static 1.52.0 · شبكة 24×24 · stroke 2px. ISC، مع MIT للأيقونات المشتقة من Feather. احتفظ بالترخيص عند النسخ أو التوزيع.</p>`)+section('original','أيقونات نسق الأصلية / 26',`<div class="icon-grid">${iconNames.map(n=>`<a class="icon-cell" href="assets/icon-${n}.svg" download aria-label="تحميل ${n}">${icon(n)}<small>${n} ↓</small></a>`).join('')}</div><p class="nq-help">مجموعة أصلية بسمك 1.75px. اختر عائلة واحدة لكل شاشة كي يبقى الإيقاع متناسقًا.</p>`)+section('usage','الاستخدام والوصول',code('<button class="nq-button secondary" aria-label="ابحث">\n <img src="assets/lucide/search.svg" width="24" height="24" alt="">\n</button>')+`<p>الأيقونة الزخرفية alt فارغ. زر الأيقونة يحتاج تسمية وفعلًا واضحًا ومساحة لمس 44px. لا تعكس البحث أو الصوت أو الشعار. الأسهم والأيقونات الاتجاهية تحتاج RTL/LTR مناسبًا. لوراثة لون النص ضمّن SVG باستخدام currentColor؛ الصور المرتبطة تستخدم اللون الافتراضي.</p>`)}
function lucideCells(items){return items.map(x=>`<div class="lucide-cell"><a href="assets/lucide/${x.name}.svg" download aria-label="تحميل ${x.name}"><img loading="lazy" src="assets/lucide/${x.name}.svg" width="24" height="24" alt=""><small dir="ltr">${x.name}</small></a><button data-copy="assets/lucide/${x.name}.svg" aria-label="نسخ مسار ${x.name}">Path ⧉</button></div>`).join('')}
function wireLucide(){const input=$('#lucide-search');if(!input)return;let limit=72;const arabic={'بحث':'search','محادثة':'message','مساعد':'bot','صوت':'audio','ملف':'file','فريق':'users','إعدادات':'settings','تحميل':'download','قلب':'heart'};const categories={ai:/bot|brain|message|sparkles|workflow|wand|scan|lightbulb/,navigation:/arrow|chevron|menu|search|check|plus|minus|^x$|move|home/,files:/file|folder|book|notebook|archive|clipboard|paperclip|upload|download/,data:/chart|database|table|gauge|activity|sliders|layout|monitor/,media:/audio|mic|headphone|volume|video|camera|image|play|pause|music/,commerce:/credit|wallet|receipt|users|user|badge|building|handshake|shopping|ticket/};const update=()=>{const raw=input.value.trim().toLowerCase(),q=arabic[raw]||raw,cat=$('#lucide-category').value;const items=lucideIcons.filter(x=>(x.name+' '+x.tags.join(' ')).includes(q)&&(cat==='all'||categories[cat].test(x.name)));$('#lucide-grid').innerHTML=items.length?lucideCells(items.slice(0,limit)):'<p>لا توجد أيقونات مطابقة. جرّب كلمة أخرى.</p>';$('#lucide-count').textContent=`${items.length} أيقونة مطابقة · عرض ${Math.min(limit,items.length)}`;$('#lucide-more').hidden=limit>=items.length;$('#lucide-grid').style.setProperty('--icon-preview-size',$('#lucide-size').value+'px')};input.addEventListener('input',()=>{limit=72;update()});$('#lucide-category').addEventListener('change',()=>{limit=72;update()});$('#lucide-size').addEventListener('change',update);$('#lucide-more').addEventListener('click',()=>{limit+=72;update()});update()}
function motion(){return head('motion','حركة قصيرة تشرح التغيير، وتفاعل يحترم المستخدم. المتغيرات تغطي الوقت والمنحنى والمسافة، ثم تربطها المكونات بإجراءات واضحة.')+section('motion-tokens','متغيرات الحركة',table(['Token','القيمة','الاستخدام'],Object.entries(foundationTokens.motion.duration).map(([n,t])=>['motion.duration.'+n,t.$value.value+'ms',t.$description]))+table(['Easing','القيمة','المعنى'],Object.entries(foundationTokens.motion.easing).map(([n,t])=>[n,'cubic-bezier('+t.$value.join(', ')+')',t.$description]))+code('interaction.reveal.duration → motion.duration.slow → 320ms\ninteraction.reveal.easing   → motion.easing.enter\nmotion.distance.md         → 8px\nmotion.scale.pressed       → 0.98'))+section('motion-demos','جرّب الحركة والتفاعل',`<label class="nq-check"><input type="checkbox" id="motion-reduce"> تقليل الحركة في الأمثلة</label><p class="nq-help">يحترم النظام أيضًا تفضيل reduced-motion في جهازك. التركيز يظهر فورًا، ولا يخفيه أي انتقال.</p><div id="motion-demo-region" class="motion-demo-grid"><article class="nq-card"><small class="eyebrow">01 / EASING</small><h3>بداية، ووصول.</h3><div class="motion-track"><i id="motion-dot" aria-hidden="true"></i></div><label for="motion-easing">المنحنى</label><select id="motion-easing" class="nq-select">${Object.keys(foundationTokens.motion.easing).map(n=>`<option value="${n}">${n}</option>`).join('')}</select><button id="motion-run" class="nq-button secondary">حرّك النقطة</button><p id="motion-run-status" class="nq-help" role="status">مثال حركة؛ لا يمثل تقدم عملية.</p></article><article class="nq-card"><small class="eyebrow">02 / REVEAL</small><h3>محتوى عند الطلب.</h3><button id="motion-reveal-toggle" class="nq-button secondary" aria-expanded="false" aria-controls="motion-reveal-content">أظهر التفاصيل</button><div id="motion-reveal-content" class="nq-enter motion-reveal-content" hidden><b>التفاصيل أصبحت متاحة.</b><p>إزاحة 8px، مدة 320ms. يبقى المحتوى في ترتيب قراءة طبيعي.</p></div></article><article class="nq-card"><small class="eyebrow">03 / PRESS + FOCUS</small><h3>استجابة صغيرة.</h3><button class="nq-button" data-toast="تم اختيار الإجراء التوضيحي">جرّب النقر أو Space</button><p class="nq-help">Hover 120ms؛ press scale 0.98؛ Focus فوري. جرّب Tab ثم Space.</p><label class="nq-check"><input type="checkbox" class="nq-switch" role="switch"> حفظ السجل — مثال محلي</label></article><article class="nq-card"><small class="eyebrow">04 / DIALOG</small><h3>قرار في مكانه.</h3><button class="nq-button secondary" data-open="motion-dialog">افتح النافذة</button><dialog id="motion-dialog" class="nq-dialog nq-motion-dialog" aria-labelledby="motion-dialog-title"><h2 id="motion-dialog-title">نافذة توضيحية</h2><p>دخول 200ms. Escape يغلق ويعيد التركيز. لا تؤخر الإغلاق.</p><button class="nq-button secondary" data-close="motion-dialog">إغلاق</button></dialog></article><article class="nq-card"><small class="eyebrow">05 / LOADING</small><h3>حركة، بلا ادعاء.</h3><div class="motion-loading-row"><span id="motion-loader" class="nq-spinner" aria-hidden="true" hidden></span><span id="motion-loading-status" role="status">العرض متوقف.</span></div><button id="motion-loading-toggle" class="nq-button secondary" aria-pressed="false">شغّل المثال</button><p class="nq-help">تشغيل محلي للحركة فقط. لا طلب ولا توليد AI. أوقف التحميل عند الوصول أو الخطأ في المنتج الحقيقي.</p></article><article class="nq-card"><small class="eyebrow">06 / DISCLOSURE</small><h3>تفاعل أصلي.</h3><details class="nq-accordion"><summary>ما الذي يحدث عند تقليل الحركة؟</summary><p>لا انتقال ولا دوران. تبقى الحالات والنصوص والأفعال واضحة وقابلة للاستخدام.</p></details><div class="nq-tooltip-wrap"><button class="nq-button secondary" aria-describedby="motion-tip">مساعدة إضافية</button><span class="nq-tooltip" id="motion-tip" role="tooltip">Hover / Focus / Escape</span></div></article></div>`)+section('interaction-map','وصفات التفاعل',table(['التفاعل','المشغّل','سلوك الحالة','الوصول'],[['Hover','Pointer','تغيير صغير بلا تحريك تخطيط','لا معلومات حصرية للتحويم'],['Focus','Tab / Keyboard','حلقة مرئية فورية','لا تلغِ outline'],['Press','Click / Space / Enter','رد فعل قصير ثم تنفيذ الفعل','disabled يمنع التنفيذ'],['Reveal','Button','aria-expanded + hidden','ترتيب DOM ثابت'],['Dialog','showModal / close','دخول خفيف، إغلاق فوري','Escape + استرجاع التركيز'],['Switch','Click / Space','تغيّر checked، تحرّك thumb','تسمية ثابتة + role=switch'],['Loading','عمل فعلي','حالة نصية + stop/retry عند الحاجة','aria-busy عند تحميل المحتوى']]))+section('motion-code','الوصفة في مشروعك',code('.nq-enter {\n animation:nq-enter var(--nq-interaction-reveal-duration)\n           var(--nq-interaction-reveal-easing) both;\n}\n@keyframes nq-enter {\n from {opacity:0;transform:translateY(var(--nq-motion-distance-md))}\n to   {opacity:1;transform:translateY(0)}\n}\n@media (prefers-reduced-motion:reduce) {\n *, *::before, *::after {animation:none!important;transition:none!important}\n}')+`<p>المدة متغير تصميم؛ أما click وfocus وchecked فهي حالات أصلية تحتاج منطقًا دلاليًا. لا تحوّل أسماء الأحداث إلى ألوان أو توقيتات ثابتة في كل شاشة. <a class="tag-link" href="downloads/motion.html">افتح الأمثلة المستقلة ↗</a></p>`)}
function wireMotion(){const region=$('#motion-demo-region');if(!region)return;$('#motion-reduce').addEventListener('change',e=>{region.dataset.motion=e.target.checked?'reduce':'full'});let shifted=false;$('#motion-run').addEventListener('click',()=>{shifted=!shifted;const dot=$('#motion-dot');dot.style.transitionTimingFunction=`var(--nq-motion-easing-${$('#motion-easing').value})`;dot.classList.toggle('shifted',shifted);$('#motion-run-status').textContent=shifted?'وصلت النقطة إلى النهاية.':'عادت النقطة إلى البداية.'});$('#motion-reveal-toggle').addEventListener('click',e=>{const expanded=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',expanded);e.currentTarget.textContent=expanded?'أخفِ التفاصيل':'أظهر التفاصيل';$('#motion-reveal-content').hidden=!expanded});$('#motion-loading-toggle').addEventListener('click',e=>{const running=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',running);e.currentTarget.textContent=running?'أوقف المثال':'شغّل المثال';$('#motion-loader').hidden=!running;$('#motion-loading-status').textContent=running?'جارٍ عرض حركة التحميل التوضيحية.':'العرض متوقف.'})}

const bilingualTypography=typography;
typography=function(){return bilingualTypography()+section('english','English / الرفيق الإنجليزي',`<p>المراعي للعربية، وInter للإنجليزية. الهوية والألوان والهندسة مشتركة؛ لكل لغة اتجاهها وإيقاع القراءة. استخدم lang وdir معًا، واعزل الأسماء والبيانات المختلطة باستخدام bdi.</p><div class="locale-pair"><div class="nq" lang="ar" dir="rtl"><h3 class="nq-type-heading-lg">الأفكار تستحق الوضوح.</h3><p class="nq-type-body-md">المراعي · 16px / 1.8</p></div><div class="nq" lang="en" dir="ltr"><h3 class="nq-type-heading-lg">Ideas deserve clarity.</h3><p class="nq-type-body-md">Inter · 16px / 1.6</p></div></div>`+table(['اللغة','متغيرات الخط','الاتجاه'],[['العربية','type.* · Almarai','lang=ar / dir=rtl'],['English','type-en.* · Inter','lang=en / dir=ltr']])+`<div class="nq" lang="en" dir="ltr">${Object.entries(foundationTokens['type-en']).map(([name,t])=>`<article class="type-style"><small>type-en.${name}</small><p class="nq-type-${name}">${name==='code'?'const language = "en";':name==='data'?'12,840':'Your ideas, with Nasaq.'}</p></article>`).join('')}</div><a class="tag-link" href="en.html#typography">افتح توثيق الخطوط بالإنجليزية ↗</a>`)};
const bilingualMcp=mcp;
mcp=function(){return bilingualMcp()+section('languages','مكتبة بلغتين',`<p>العربية هي الافتراضي. للحصول على HTML وحالات ومركبات إنجليزية، أرسل language=en إلى get_component وget_pattern وsearch_nasaq. المتغيرات type-en.* للخط الإنجليزي، وtype.* للعربية.</p>`+code('get_component({id:"switch", language:"en"})\nget_pattern({id:"chat", language:"en"})'))};

function npm(){return head('npm','حزمة جاهزة للمطورين: CSS، متغيرات مكتوبة الأنواع، خطوط محلية، أيقونات، وتفاعل أصلي. تدعم العربية والإنجليزية دون اعتماديات تشغيل.')+section('install','التثبيت الآن',`<div class="nq-card"><b dir="ltr">@nasaq/ui · 1.3.0</b><p>حزمة محلية قابلة للتثبيت. لم تُنشر في سجل npm بعد. حمّل الملف وضعه في جذر مشروعك ثم نفّذ الأمر.</p><a class="nq-button secondary" href="downloads/nasaq-ui-1.3.0.tgz" download>حمّل حزمة npm ↓</a></div>`+code('npm install ./nasaq-ui-1.3.0.tgz'))+section('vanilla','JavaScript / Vite',code('import "@nasaq/ui/styles.css";\nimport { initNasaq, getToken } from "@nasaq/ui";\n\nconst cleanup = initNasaq(document);\nconsole.log(getToken("type.body-md"));\n// استدعِ cleanup() عند إزالة الواجهة.')+code('<html lang="ar" dir="rtl">\n <body class="nq">\n  <button class="nq-button">ابدأ الكتابة</button>\n  <section class="nq" lang="en" dir="ltr">\n   <p class="nq-type-body-md">Your ideas, in your voice.</p>\n  </section>\n </body>\n</html>'))+section('react','React / Next.js',`<p>استخدم عناصر HTML الأصلية مع className. الحزمة لا تحتوي أغلفة React جاهزة. استورد CSS مرة واحدة في مدخل الأنماط العام. شغّل التفاعل في عميل المتصفح فقط، مع تنظيفه عند الإزالة.</p>`+code("'use client';\nimport { useEffect } from 'react';\nimport { initNasaq } from '@nasaq/ui';\n\nexport function NasaqBehavior() {\n useEffect(() => initNasaq(document), []);\n return null;\n}")+`<p>ضع lang وdir على html، وclassName="nq" على body. استدعاء JavaScript أثناء SSR آمن ولا يصل إلى document تلقائيًا. ركّب مساعد التفاعل مرة واحدة؛ لا تستخدم جذورًا متداخلة.</p>`)+section('exports','ما الذي توفره الحزمة؟',table(['المسار / API','الاستخدام'],[['@nasaq/ui/styles.css','CSS ومراجع الخطوط المحلية'],['initNasaq(root?)','Tabs / Dialog / Tooltip + cleanup'],['getToken(name)','حل المراجع، بما فيها المتغيرات المركّبة'],['tokens / tokenNames / version','قيم DTCG + مسارات TypeScript'],['tokens.json','مصدر المتغيرات'],['components.json / components.en.json','18 مكوّنًا وحالاته بالعربية والإنجليزية'],['patterns.json / patterns.en.json','12 تركيبًا لكل لغة'],['icons/*.svg / assets/*','Lucide + الخطوط والرموز الأصلية']])+code("import searchUrl from '@nasaq/ui/icons/search.svg?url';\n// Vite: ضعه داخل img مع تسمية مفهومة للزر."))+section('ownership','التطوير والنشر',`<p>يتولى مشروعك البيانات والتوليد والفوترة والحفظ الفعلي. التبديلات الأصلية لا تحتاج JavaScript إضافيًا. الأنماط تُحترم في الوضعين وتدعم reduced-motion. تراخيص MIT لأصول نسق الأصلية، وOFL للخطوط، وتراخيص Lucide/Feather مرفقة.</p><p>تُبنى الحزمة من نفس مصادر الموقع. أمر npm pack المحلي ينشئ ملفًا قابلًا للتثبيت دون نشره. النشر في السجل يحتاج التحقق من ملكية النطاق @nasaq والإصدار؛ بعد النشر فقط يصبح npm install @nasaq/ui صالحًا لهذا الإصدار.</p><a class="tag-link" href="https://docs.npmjs.com/cli/v12/commands/npm-pack/">توثيق npm pack ↗</a>`)}

const renderers={npm,motion,brand,'ai-guide':aiGuide,mcp,overview,start,colors,typography,logos,icons,misc,effects,spacing,marketing,patterns,tokens,skill,downloads};
let renderSerial=0;
async function render(){const serial=++renderSerial;const id=location.hash.slice(1)||'overview';const valid=pages.some(p=>p[0]===id)?id:'overview';const html=examples[valid]?component(valid):await renderers[valid]();if(serial!==renderSerial)return;$('#main').innerHTML=html+footer();$('#language-switch').href='en.html#'+valid;document.title=`${pages.find(p=>p[0]===valid)[1]} — نسق Nasaq`;document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===valid);if(a.dataset.page===valid)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#toc').innerHTML='<p>في هذه الصفحة</p>'+[...document.querySelectorAll('main .section')].map(s=>`<a href="#${valid}" data-scroll="${s.id}">${s.querySelector('h2')?.textContent||''}</a>`).join('');$('.sidebar').classList.remove('open');$('#nav-toggle').setAttribute('aria-expanded','false');window.scrollTo(0,0);wire();if(valid==='tokens')loadTokens();}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
async function copy(s){try{await navigator.clipboard.writeText(s);toast('تم النسخ')}catch{const t=document.createElement('textarea');t.value=s;document.body.appendChild(t);t.select();const ok=document.execCommand('copy');t.remove();toast(ok?'تم النسخ':'تعذر النسخ. حدّد النص وانسخه يدويًا.')}}
function wire(){wireLucide();wireMotion();document.querySelectorAll("[data-indeterminate]").forEach(i=>i.indeterminate=true);const f=$('#input-demo');if(f)f.addEventListener('submit',e=>{e.preventDefault();toast('صيغة البريد صحيحة — لم يتم إرسال بيانات.');});const sel=$('#assistant-select');if(sel)sel.addEventListener('change',()=>$('#select-status').textContent='المساعد الحالي: '+sel.value);const n=$('#newsletter-demo');if(n)n.addEventListener('submit',e=>{e.preventDefault();$('#newsletter-status').textContent='تم التحقق من صيغة البريد. هذا مثال محلي، ولم يتم تسجيل اشتراك.'});const chat=$('#chat-form');if(chat)chat.addEventListener('submit',e=>{e.preventDefault();let input=$('#chat-prompt');const value=input.value.trim();if(!value)return;$('#chat-log').insertAdjacentHTML('beforeend',`<div class="chat-message user"><b>أنت</b><p>${esc(value)}</p></div><div class="chat-message"><b>نسق · رد توضيحي</b><p>لنبدأ بتحديد الفكرة الأساسية، ثم ترتيبها في مقدمة وثلاث نقاط وخاتمة قصيرة. هذا رد ثابت يوضح تصميم المحادثة.</p><button class="nq-button secondary small" data-copy="لنبدأ بتحديد الفكرة الأساسية، ثم ترتيبها في مقدمة وثلاث نقاط وخاتمة قصيرة.">نسخ الرد</button></div>`);input.value='';input.focus();});if($('#knowledge-search')){const update=()=>{const q=$('#knowledge-search').value.toLowerCase();const items=[['الكتابة العربية','أسلوب واضح ومباشر.','typography'],['البحث والمعرفة','معلومات منظمة ومصادر قابلة للمراجعة.','patterns'],['إعداد المشروع','ملفات جاهزة للبدء.','start']].filter(r=>(r[0]+r[1]).toLowerCase().includes(q));$('#knowledge-results').innerHTML=items.length?items.map(r=>`<a href="#${r[2]}"><span><b>${r[0]}</b><small style="display:block">${r[1]}</small></span><span>↖</span></a>`).join(''):'<p role="status">لا توجد نتائج. جرّب كلمة أخرى.</p>'};$('#knowledge-search').addEventListener('input',update);update();}}
async function loadTokens(){try{tokenData=tokenData||window.NASAQ_TOKENS||await (await fetch('downloads/tokens.json')).json();function flatten(o,p=''){return Object.entries(o).flatMap(([k,v])=>k.startsWith('$')?[]:v.$type?[[p+k,v.$type,v.$value]]:flatten(v,p+k+'.'))};const all=flatten(tokenData);const update=()=>{const q=$('#token-filter').value.toLowerCase();const rows=all.filter(r=>r[0].toLowerCase().includes(q));$('#token-count').textContent=rows.length+' متغيرًا';$('#token-table').innerHTML=table(['الاسم','النوع','القيمة'],rows.map(r=>{let v=r[2], val=typeof v==='string'?v:Array.isArray(v)?v.join(', '):v.hex||JSON.stringify(v);return [`<button class="token-name" style="background:none;border:0;color:var(--nq-link);cursor:pointer" data-copy="${esc(r[0])}">${esc(r[0])} ⧉</button>`,r[1],`${v.hex?`<i class="token-preview" style="background:${v.hex}"></i>`:''}<code>${esc(val)}</code>`]}));};$('#token-filter').addEventListener('input',update);update()}catch{$('#token-table').innerHTML='<p>تعذر عرض المتغيرات. افتح الموقع عبر خادم محلي، أو حمّل tokens.json مباشرة.</p>'}}
function search(q=''){let rows=pages.filter(p=>p.join(' ').toLowerCase().includes(q.toLowerCase()));$('#search-results').innerHTML=rows.length?rows.map(p=>`<a href="#${p[0]}" data-search-result>${p[1]} <small>${p[2]} ↖</small></a>`).join(''):'<p role="status">لا توجد نتائج.</p>'}
$('#search-open').addEventListener('click',()=>{search();$('#search-dialog').showModal();$('#search-input').focus()});$('#search-input').addEventListener('input',e=>search(e.target.value));
try{if(localStorage.getItem('nasaq-theme')==='dark')document.documentElement.dataset.theme='dark'}catch{}
$('#theme').addEventListener('click',()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('nasaq-theme',t)}catch{}toast(t==='dark'?'المظهر الليلي':'المظهر النهاري')});
$('#nav-toggle').addEventListener('click',()=>{let open=$('.sidebar').classList.toggle('open');$('#nav-toggle').setAttribute('aria-expanded',open)});
document.addEventListener('click',e=>{const b=e.target.closest('[data-copy],[data-toast],[data-open],[data-close],[data-scroll],[data-search-result]');if(!b)return;if(b.hasAttribute('data-copy'))copy(b.dataset.copy);if(b.dataset.toast)toast(b.dataset.toast);if(b.dataset.scroll){e.preventDefault();document.getElementById(b.dataset.scroll).scrollIntoView({behavior:'smooth'})}if(b.hasAttribute('data-search-result'))$('#search-dialog').close()});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search-open').click()}});
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()});
window.addEventListener('hashchange',()=>{render();$('#main').focus()});render();
